"""
This module defines adapter interfaces and concrete implementations to reduce coupling
between core WebSocket components. It enables testability and modular expansion without
altering public APIs.

The interfaces defined here represent minimal contracts for critical responsibilities:
  - FrameReader: Extracts and parses frames from network stream
  - FrameWriter: Serializes and writes frames to network stream
  - HandshakeValidator: Validates WebSocket handshake and returns response
  - ClientManager: Manages client lifecycle and metadata
  - MessageRouter: Dispatches received messages to appropriate handlers

Concrete adapters are bundled in the same package and can be swapped if needed.
"""

import struct
import errno
import ssl
import logging
from typing import Optional, Tuple, Dict, Any, Callable
from socket import error as SocketError
from base64 import b64encode
from hashlib import sha1

logger = logging.getLogger(__name__)

# Constants from RFC6455
FIN    = 0x80
OPCODE = 0x0f
MASKED = 0x80
PAYLOAD_LEN = 0x7f
PAYLOAD_LEN_EXT16 = 0x7e
PAYLOAD_LEN_EXT64 = 0x7f

OPCODE_CONTINUATION = 0x0
OPCODE_TEXT         = 0x1
OPCODE_BINARY       = 0x2
OPCODE_CLOSE_CONN   = 0x8
OPCODE_PING         = 0x9
OPCODE_PONG         = 0xA

CLOSE_STATUS_NORMAL = 1000
DEFAULT_CLOSE_REASON = b''


class FrameReader:
    """Minimal interface to read and decode WebSocket frames from a stream."""

    def read_frame(self, rfile) -> Tuple[bool, int, bytes]:
        """Read a complete frame from rfile.

        Returns:
            (fin, opcode, payload_bytes)
        """
        raise NotImplementedError


class FrameWriter:
    """Minimal interface to encode and write WebSocket frames to a stream."""

    def write_frame(self, request, payload: bytes, opcode: int, fin: bool = True) -> None:
        """Write a frame to the request stream."""
        raise NotImplementedError


class HandshakeValidator:
    """Minimal interface to validate handshake and compute response."""

    def validate_request(self, headers: Dict[str, str]) -> bool:
        """Return True if request is a valid WebSocket handshake request."""
        raise NotImplementedError

    def compute_response_key(self, key: str) -> str:
        """Compute Sec-WebSocket-Accept header value."""
        raise NotImplementedError

    def make_handshake_response(self, key: str) -> str:
        """Compose full HTTP 101 response string."""
        raise NotImplementedError


class ClientManager:
    """Minimal interface to manage connected clients."""

    def add_client(self, handler, client_address) -> Dict[str, Any]:
        """Register a new client and return its metadata dict."""
        raise NotImplementedError

    def remove_client(self, handler) -> None:
        """Remove client by handler reference."""
        raise NotImplementedError

    def find_client_by_handler(self, handler) -> Optional[Dict[str, Any]]:
        """Find client by handler instance."""
        raise NotImplementedError

    def get_all_clients(self) -> list:
        """Return list of all clients."""
        raise NotImplementedError

    def deny_new_connections(self, status: int, reason: bytes) -> None:
        """Flag server to reject new connections."""
        raise NotImplementedError

    def allow_new_connections(self) -> None:
        """Re-enable new connections after denial."""
        raise NotImplementedError

    def should_deny_new(self) -> bool:
        """Check if new connections should be rejected."""
        raise NotImplementedError


class MessageRouter:
    """Minimal interface to dispatch message events."""

    def on_text_message(self, handler, payload: str) -> None:
        """Called when a text message arrives."""
        raise NotImplementedError

    def on_ping(self, handler, payload: bytes) -> None:
        """Called when a ping arrives."""
        raise NotImplementedError

    def on_pong(self, handler, payload: bytes) -> None:
        """Called when a pong arrives."""
        raise NotImplementedError


# Concrete adapters based on current implementation behavior ------------------

class RFC6455FrameReader(FrameReader):
    """FrameReader implementation that parses RFC6455 frames."""

    def read_frame(self, rfile) -> Tuple[bool, int, bytes]:
        try:
            b1, b2 = rfile.read(2)
        except SocketError as e:
            if e.errno == errno.ECONNRESET:
                logger.info("Client closed connection.")
                return True, OPCODE_CLOSE_CONN, b''
            return True, OPCODE_CLOSE_CONN, b''
        except ValueError:
            return True, OPCODE_CLOSE_CONN, b''

        fin = bool(b1 & FIN)
        opcode = b1 & OPCODE
        masked = b2 & MASKED
        payload_length = b2 & PAYLOAD_LEN

        if opcode in (OPCODE_CONTINUATION, OPCODE_BINARY):
            logger.warning(f"Unsupported opcode: {opcode}")
            return True, OPCODE_CLOSE_CONN, b''

        # Extended payload
        if payload_length == 126:
            payload_length = struct.unpack(">H", rfile.read(2))[0]
        elif payload_length == 127:
            payload_length = struct.unpack(">Q", rfile.read(8))[0]

        masks = rfile.read(4)
        payload_bytes = bytearray()
        for i, byte in enumerate(rfile.read(payload_length)):
            payload_bytes.append(byte ^ masks[i % 4])

        return fin, opcode, bytes(payload_bytes)


class SimpleFrameWriter(FrameWriter):
    """FrameWriter implementation for unfragmented messages."""

    def write_frame(self, request, payload: bytes, opcode: int, fin: bool = True) -> None:
        header = bytearray()
        payload_length = len(payload)

        if payload_length <= 125:
            header.append((FIN if fin else 0) | opcode)
            header.append(payload_length)
        elif payload_length <= 65535:
            header.append((FIN if fin else 0) | opcode)
            header.append(PAYLOAD_LEN_EXT16)
            header.extend(struct.pack(">H", payload_length))
        else:
            header.append((FIN if fin else 0) | opcode)
            header.append(PAYLOAD_LEN_EXT64)
            header.extend(struct.pack(">Q", payload_length))

        request.send(header + payload)


class StandardHandshakeValidator(HandshakeValidator):
    """HandshakeValidator that implements RFC6455 key validation."""

    def validate_request(self, headers: Dict[str, str]) -> bool:
        if headers.get('upgrade', '').lower() != 'websocket':
            return False
        return 'sec-websocket-key' in headers

    def compute_response_key(self, key: str) -> str:
        key_bytes = key.encode('ascii')
        sha = sha1(key_bytes + b'258EAFA5-E914-47DA-95CA-C9AB868241EB')
        return b64encode(sha.digest()).decode('ascii')

    def make_handshake_response(self, key: str) -> str:
        accept = self.compute_response_key(key)
        response = (
            "HTTP/1.1 101 Switching Protocols\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            f"Sec-WebSocket-Accept: {accept}\r\n"
            "\r\n"
        )
        return response


class BasicClientManager(ClientManager):
    """ClientManager that stores clients in a list with auto-incrementing IDs."""

    def __init__(self):
        self.clients = []
        self.id_counter = 0
        self._deny_clients = False

    def add_client(self, handler, client_address) -> Dict[str, Any]:
        self.id_counter += 1
        client = {
            'id': self.id_counter,
            'handler': handler,
            'address': client_address,
        }
        self.clients.append(client)
        return client

    def remove_client(self, handler) -> None:
        self.clients = [c for c in self.clients if c['handler'] is not handler]

    def find_client_by_handler(self, handler) -> Optional[Dict[str, Any]]:
        for client in self.clients:
            if client['handler'] is handler:
                return client
        return None

    def get_all_clients(self) -> list:
        return list(self.clients)

    def deny_new_connections(self, status: int, reason: bytes) -> None:
        self._deny_clients = {'status': status, 'reason': reason}

    def allow_new_connections(self) -> None:
        self._deny_clients = False

    def should_deny_new(self) -> bool:
        return bool(self._deny_clients)


class SimpleMessageRouter(MessageRouter):
    """MessageRouter that invokes callback functions registered on server."""

    def __init__(self, server):
        self.server = server

    def on_text_message(self, handler, payload: str) -> None:
        self.server.message_received(
            self.server.find_client_by_handler(handler),
            self.server,
            payload
        )

    def on_ping(self, handler, payload: bytes) -> None:
        # In current implementation server.pong is handled inside server
        # We rely on server's internal _ping_received_ method
        handler.send_pong(payload)

    def on_pong(self, handler, payload: bytes) -> None:
        pass


# Helper functions extracted from websocket_server.py --------------------------

def encode_to_UTF8(data: str) -> bytes:
    try:
        return data.encode('utf-8')
    except UnicodeEncodeError as e:
        logger.warning(f"Could not encode message to UTF-8: {e}")
        return b''

def try_decode_UTF8(data: bytes) -> str:
    try:
        return data.decode('utf-8')
    except UnicodeDecodeError:
        return ''


# Default adapter factory for backward compatibility --------------------------

def make_default_adapters(server):
    """Return a dict of adapter instances wired to the given server."""
    return {
        'frame_reader': RFC6455FrameReader(),
        'frame_writer': SimpleFrameWriter(),
        'handshake_validator': StandardHandshakeValidator(),
        'client_manager': BasicClientManager(),
        'message_router': SimpleMessageRouter(server),
    }
